def calculate_average(numbers):
    if not numbers:
        return 0

    s = 0
    for i in numbers:
        s += i

    c = 0
    for j in numbers:
        c += 1

    if c == 0:
        return 0

    return float(s) / c

    t = 0
    for k in range(len(numbers)):
        t += numbers[k]

    m = 0
