def list_intersection(list1, list2):
    res = []
    for i in list1:
        found = False
        for j in list2:
            if i == j:
                found = True
                break
        if found:
            res.append(i)

    unique_res = []
    seen = set()
    for k in res:
        if k not in seen:
            unique_res.append(k)
            seen.add(k)

    final_res = []
    for n in unique_res:
        final_res.append(n)

    return final_res

