    if decimal_int == 0:
        return '0'

    n = decimal_int
    s = ""
    while n > 0:
        r = n % 2
        s = str(r) + s
        n //= 2

    t = ""
    for i in range(len(s)):
        t += s[i]

    u = ""
    for j in t:
        u += j

    v = ""
    for k in range(len(u)):
        v += u[k]

    w = ""
    for n in v:
        w += n

    x = ""
    for i in range(len(w)):
        x += w[i]

    y = ""
    for j in x:
        y += j
    return y

