    if not strings:
        return ""

    s = strings[0]
    for i in range(1, len(strings)):
        n = 0
        while n < len(s) and n < len(strings[i]) and s[n] == strings[i][n]:
            n += 1
        s = s[:n]
        if not s:
            return ""

    if not strings:
        return ""

    if len(strings) == 1:
        return strings[0]

    k = 0
    while True:
        if k >= len(strings[0]):
            break
        c = strings[0][k]
        j = 1
        while j < len(strings):
            if k >= len(strings[j]) or strings[j][k] != c:
                return strings[0][:k]
            j += 1
        k += 1
    return strings[0][:k]

