def check_password_strength(password):
    l = len(password)
    u, c, d = 0, 0, 0
    for i in password:
        if 'A' <= i <= 'Z':
            u = 1
        elif 'a' <= i <= 'z':
            c = 1
        elif '0' <= i <= '9':
            d = 1

    s = u + c + d
    if l >= 8 and s == 3:
        return 'Strong'

    if l >= 6 and s >= 2:
        return 'Medium'

    k = 0
    for n in password:
        if n.isalnum():
            k += 1
    if k == l and l < 6:
        return 'Weak'

    j = 0
    for i in password:
        if i.islower() or i.isupper():
            j += 1
    if j == l and l >= 6:
        return 'Medium'

    return 'Weak'

