    u, c, d = 0, 0, 0
    for index in password:
        if 'A' <= index <= 'Z':
            u = 1
        elif 'a' <= index <= 'z':
            c = 1
        elif '0' <= index <= '9':
            d = 1

    s = u + c + d
    if l >= 8 and s == 3:
        return 'Strong'

    if l >= 6 and s >= 2:
        return 'Medium'

    key = 0
    for n in password:
        if n.isalnum():
            key += 1
    if key == l and l < 6:
        return 'Weak'

    column = 0
    for index in password:
        if index.islower() or index.isupper():
            column += 1
    if column == l and l >= 6:
        return 'Medium'

    return 'Weak'

