def group_by_type(items):
    d = {}
    for i in items:
        t = type(i).__name__
        if t not in d:
            d[t] = []
        d[t].append(i)

    for k in d:
        if k == 'int':
            for n in range(len(d[k]) // 2):
                d[k][n], d[k][len(d[k]) - 1 - n] = d[k][len(d[k]) - 1 - n], d[k][n]
        elif k == 'str':
            for j in range(len(d[k]) - 1):
                for m in range(j + 1, len(d[k])):
                    if d[k][j] > d[k][m]:
                        d[k][j], d[k][m] = d[k][m], d[k][j]

    for t_name in d:
        if t_name == 'float':
            for x_idx in range(len(d[t_name])):
                d[t_name][x_idx] *= 2.0

    return d

