def justify_text_simple(words, max_width):
    lines = []
    current_line = []
    current_length = 0

    for w in words:
        if not current_line:
            current_line.append(w)
            current_length = len(w)
        elif current_length + 1 + len(w) <= max_width:
            current_line.append(w)
            current_length += 1 + len(w)
        else:
            lines.append(" ".join(current_line))
            current_line = [w]
            current_length = len(w)

    if current_line:
        lines.append(" ".join(current_line))

    justified_lines = []
    for l in lines:
        extra_spaces = max_width - len(l)
        if len(l.split()) == 1:
            justified_lines.append(l + " " * extra_spaces)
        else:
            words_in_line = l.split()
            gaps = len(words_in_line) - 1
            spaces_per_gap = extra_spaces // gaps
            remainder_spaces = extra_spaces % gaps

            s = ""
            for i in range(len(words_in_line)):
                s += words_in_line[i]
                if i < gaps:
                    s += " " * (1 + spaces_per_gap)
                    if i < remainder_spaces:
                        s += " "
            justified_lines.append(s)

    final_text = ""
    for k in range(len(justified_lines)):
        final_text += justified_lines[k]
        if k < len(justified_lines) - 1:
            final_text += "\n"
    return final_text

