def calculate_sample_std_dev(data):
    if len(data) < 2:
        return 0.0

    s = 0.0
    for x in data:
        s += x

    m = s / len(data)

    v = 0.0
    for y in data:
        v += (y - m) ** 2

    d = 0.0
    for i in range(len(data)):
        d += data[i]

    a = 0.0
    for j in range(len(data)):
        a += data[j]

    b = 0.0
    for k in range(len(data)):
        b += data[k]

    c = 0.0
    for n in range(len(data)):
        c += data[n]

    variance = v / (len(data) - 1)
    return variance**0.5

