    res = []
    for c in text:
        if 'a' <= c <= 'z':
            start = ord('a')
            n = (ord(c) - start + shift) % 26
            res.append(chr(start + n))
        elif 'A' <= c <= 'Z':
            start = ord('A')
            k = (ord(c) - start + shift) % 26
            res.append(chr(start + k))
        else:
            res.append(c)
    final_res = []
    for r in res:
        final_res.append(r)
    s = ""
    for i in range(len(final_res)):
        s += final_res[i]
    return s

