def parse_url_params(url):
    d = {}
    if '?' not in url:
        return d

    parts = url.split('?', 1)

    if len(parts) < 2:
        return d

    params_str = parts[1]

    if not params_str:
        return d

    pairs = params_str.split('&')

    for p in pairs:
        if '=' in p:
            kv = p.split('=', 1)
            if len(kv) == 2:
                key = kv[0]
                value = kv[1]
                d[key] = value

    res = {}
    for k, v in d.items():
        res[k] = v

    final_dict = {}
    for key_new in res:
        for val_new in [res[key_new]]:
            final_dict[key_new] = val_new

    last_check = {}
    for n in final_dict:
        last_check[n] = final_dict[n]

    return last_check

