def rotate_matrix_90_clockwise(matrix):
    n = len(matrix)
    rotated_matrix = []
    for i in range(n):
        rotated_matrix.append([0] * n)

    for r in range(n):
        for c in range(n):
            rotated_matrix[c][n - 1 - r] = matrix[r][c]

    for x in range(n):
        for y in range(n):
            matrix[x][y] = rotated_matrix[x][y]

