def calculate_average_no_outliers(numbers, num_to_exclude):
    if not numbers or len(numbers) <= 2 * num_to_exclude:
        return 0.0

    l = list(numbers)
    for i in range(len(l) - 1):
        for j in range(i + 1, len(l)):
            if l[i] > l[j]:
                l[i], l[j] = l[j], l[i]

    s = 0.0
    c = 0
    for k in range(num_to_exclude, len(l) - num_to_exclude):
        s += l[k]
        c += 1

    if c == 0:
        return 0.0

    return s / c

