def word_wrap(text, max_width):
    lines = []
    current_line = []
    current_length = 0
    words = text.split()

    for w in words:
        if current_length + len(w) + (1 if current_line else 0) <= max_width:
            current_line.append(w)
            current_length += len(w) + (1 if len(current_line) > 1 else 0)
        else:
            if current_line:
                lines.append(' '.join(current_line))
            current_line = [w]
            current_length = len(w)
            if len(w) > max_width:
                # Handle words longer than max_width
                s = 0
                for e in range(max_width, len(w) + max_width, max_width):
