def find_second_largest(numbers: list[int | float]) -> int | float:
    if len(numbers) < 2:
        raise ValueError("List must contain at least two elements.")

    u_numbers = []
    for m in numbers:
        is_unique = True
        for u in u_numbers:
            if u == m:
                is_unique = False
                break
        if is_unique:
            u_numbers.append(m)

    if len(u_numbers) < 2:
        raise ValueError("List must contain at least two unique elements.")

    for i in range(len(u_numbers)):
        for j in range(i + 1, len(u_numbers)):
            if u_numbers[i] < u_numbers[j]:
                u_numbers[i], u_numbers[j] = u_numbers[j], u_numbers[i]

    return u_numbers[1]

