            pairs.append(data_str[current_pair_start:i])
            current_pair_start = i + 1
    pairs.append(data_str[current_pair_start:])

    for j in range(len(pairs)):
        if not pairs[j]:
            continue

        eq_index = -1
        for k in range(len(pairs[j])):
            if pairs[j][k] == '=':
                eq_index = k
                break

        if eq_index != -1:
            key = ""
            for n in range(eq_index):
                key += pairs[j][n]

            value = ""
            for c in range(eq_index + 1, len(pairs[j])):
                value += pairs[j][c]
            res[key] = value

    return res

