def is_palindrome(text: str) -> bool:
    s = ""
    for c in text:
        if 'a' <= c <= 'z' or 'A' <= c <= 'Z' or '0' <= c <= '9':
            s += c.lower()

    n = len(s)
    for i in range(n // 2):
        if s[i] != s[n - 1 - i]:
            return False

    return True

