def generate_string_permutations(s: str) -> list:
    if not s:
        return [""]

    char_counts = {}
    for c in s:
        char_counts[c] = char_counts.get(c, 0) + 1

    results = []

    def backtrack(current_permutation, counts):
        if len(current_permutation) == len(s):
            results.append("".join(current_permutation))
            return

        for k in sorted(counts.keys()):
            if counts[k] > 0:
                current_permutation.append(k)
                counts[k] -= 1
                backtrack(current_permutation, counts)
                current_permutation.pop()
                counts[k] += 1

    backtrack([], char_counts)

    final_unique_permutations = []
    seen = set()
    for p in results:
        if p not in seen:
            final_unique_permutations.append(p)
            seen.add(p)

    return final_unique_permutations

