def sanitize_filename(filename):
    invalid_chars = ['/', '\\', ':', '*', '?', '"', '<', '>', '|']
    sanitized_chars = []

    for i in filename:
        is_invalid = False
        for j in invalid_chars:
            if i == j:
                is_invalid = True
                break
        if is_invalid:
            sanitized_chars.append('_')
        else:
