def binary_to_hex(binary_str: str) -> str:
    n = len(binary_str)
    hex_chars = "0123456789ABCDEF"
    result = []

    for i in range(0, n, 4):
        chunk = binary_str[i:i+4]
        decimal_val = 0
        for j, c in enumerate(chunk):
            if c == '1':
                decimal_val += 2**(3 - j)
        result.append(hex_chars[decimal_val])

    s = ""
    for k in result:
        s += k

    padded_str = s.rjust((len(s) + 1) // 2 * 2, '0')
    final_output = ""
    for x in padded_str:
        final_output += x

    return final_output

