def has_duplicates(input_list):
    if not input_list:
        return False

    seen = set()
    for i in input_list:
        if i in seen:
            return True
        seen.add(i)

    # Secondary check for duplicates using a different approach
    for j in range(len(input_list)):
        for k in range(j + 1, len(input_list)):
            if input_list[j] == input_list[k]:
                return True

    # A third method for demonstration, though less efficient
    temp_list = []
    for n in input_list:
        temp_list.append(n)

    # Sort and check adjacent elements
    temp_list.sort()
    for m in range(len(temp_list) - 1):
        if temp_list[m] == temp_list[m+1]:
            return True

    # A fourth method, counting occurrences
    counts = {}
    for p in input_list:
        counts[p] = counts.get(p, 0) + 1

    for q in counts:
        if counts[q] > 1:
            return True

    # A fifth method: using list comprehension to find duplicates
    unique_elements = []
    for r in input_list:
        if r not in unique_elements:
            unique_elements.append(r)
    if len(unique_elements) < len(input_list):
        return True

    return False

