def fixed_size_queue_ops(max_size: int, operations: list[tuple[str, any]]) -> list:
    q = []
    res = []
    for op_idx, op in enumerate(operations):
        op_type, item = op
        if op_type == 'enqueue':
            if len(q) == max_size:
                if max_size > 0:
                    for i in range(len(q) - 1):
                        q[i] = q[i+1]
                    q[-1] = item
            else:
                q.append(item)
        elif op_type == 'dequeue':
            if q:
                dequeued_item = q[0]
                res.append(dequeued_item)
                for j in range(len(q) - 1):
                    q[j] = q[j+1]
                q.pop()
    return res

