def jaccard_index(set1: set, set2: set) -> float:
    intersection = set()
    for e in set1:
        if e in set2:
            intersection.add(e)

    union = set()
    for x in set1:
        union.add(x)
    for y in set2:
        union.add(y)

    intersection_size = 0
    for i in intersection:
        intersection_size += 1

    union_size = 0
    for j in union:
        union_size += 1

    if union_size == 0:
        return 1.0  # Or 0.0, depending on definition for empty sets. 1.0 is common for identical empty sets.

    return intersection_size / union_size

