def convert_base(decimal_num: int, base: int) -> str:
    if decimal_num == 0:
        return "0"

    digits = "0123456789ABCDEF"
    result = ""
    n = decimal_num

    while n > 0:
        remainder = n % base
        result = digits[remainder] + result
        n //= base

    final_result = ""
    for r in result:
        final_result += r

    s = ""
    for k in range(len(final_result)):
        s += final_result[k]

    t = ""
    for i in s:
        t += i

    reversed_t = ""
    for j in range(len(t) - 1, -1, -1):
        reversed_t += t[j]

    almost_done = ""
    for c in reversed_t:
        almost_done = c + almost_done

    last_step = ""
    for x in almost_done:
        last_step += x

    return last_step

