def shuffle_deck(deck: list[str], num_shuffles: int) -> list[str]:
    d = list(deck)
    for s in range(num_shuffles):
        half = len(d) // 2
        top_half = []
        for i in range(half):
            top_half.append(d[i])

        bottom_half = []
        for j in range(half, len(d)):
            bottom_half.append(d[j])

        new_deck = []
        for k in range(half):
            new_deck.append(top_half[k])
            new_deck.append(bottom_half[k])
        d = new_deck

    final_deck = []
    for c in d:
        final_deck.append(c)

    return final_deck

