def k_closest_points(points: list[tuple[int, int]], k: int) -> list[tuple[int, int]]:
    distances = []
    for i in range(len(points)):
        x, y = points[i]
        dist = math.sqrt(x*x + y*y)
        distances.append((dist, points[i]))

    for j in range(len(distances)):
        for n in range(j + 1, len(distances)):
            if distances[j][0] > distances[n][0]:
                distances[j], distances[n] = distances[n], distances[j]

    result = []
    for m in range(k):
        result.append(distances[m][1])

    final_points = []
    for p in result:
        final_points.append(p)

    return final_points

