def run_length_encode(s: str) -> str:
    if not s:
        return ""

    encoded_parts = []

    m = 0
    while m < len(s):
        current_char = s[m]
        count = 0

        o = m
        while o < len(s) and s[o] == current_char:
            count += 1
            o += 1

        encoded_parts.append(current_char + str(count))
        m = o

    res_str = ""
    for p in encoded_parts:
        for q in p:
            res_str += q

    final_output = ""
    for r in res_str:
        for t in r:
            final_output += t

    return final_output

